"The program and cases as one file; the case predicates' names."
function _sf_file()::Tuple{String, Vector{String}}
    names = ["t_$(id)" for (id, _) in _SF_CASES]
    text =
        _SF_PROGRAM * join([
            "t_$(id)(R) :- catch(($g), error(SfE, _), R = raised(SfE)).\n" for
            (id, g) in _SF_CASES
        ])
    f = joinpath(mktempdir(), "setflag.pl")
    write(f, text)
    return f, names
end

"The kernel's answers to the query `name(R)` in `gd`: the encoded lines, at most 50 answers; a Julia exception propagates."
function _sf_query(gd, ld, name::String)::String
    proc = LK.isCurrentProcedure(sym_key(_sfs(name)), 1, LK.MODULE_user(gd))
    if proc === nothing || !LK.isDefinedProcedure(gd, proc)
        return "$name undefined"
    end
    sols = String[]
    fid = LK.PL_open_foreign_frame(ld)
    a = LK.PL_new_term_refs(ld, 1)
    LK.putSlotValue!(ld, a + 1, mk_var(_SF, LK.fresh_var_keys!(1)), LK.PutVarMap())
    qid = LK.PL_open_query(
        gd, ld, nothing, LK.PL_Q_CATCH_EXCEPTION | LK.PL_Q_EXT_STATUS, proc, a
    )
    n = 0
    try
        while (n += 1) <= 50
            rc = LK.PL_next_solution(gd, ld, qid)
            if rc == LK.PL_S_TRUE || rc == LK.PL_S_LAST
                push!(
                    sols,
                    _sf_enc(mk_expr(_SF, _SF[_sfs(name), lk_answers(ld, (a:a)...)...]))
                )
                rc == LK.PL_S_LAST && break
            elseif rc == LK.PL_S_EXCEPTION
                push!(sols, "exception")
                break
            else
                break
            end
        end
    finally
        LK.PL_close_query(ld, qid)
        LK.PL_close_foreign_frame(ld, fid)
    end
    return "$name" * join(" " .* sols)
end

"The kernel's lines for `names` after consulting `path`, as the driver writes swipl's; the database and the local data."
function _sf_kernel(path::String, names::Vector{String})
    gd = LK.PL_global_data{_SF}()
    ld = LK.PL_local_data{_SF}(gd)
    lk_install_message_collector!(gd, ld)       # the messages are print_message/2's (LB4 b2)
    st, ball = LK.load_file!(gd, ld, path)
    out = [st === :ok ? "ok" : "exc " * _sf_enc(ball::_SF)]
    for name in names
        push!(out, _sf_query(gd, ld, name))
    end
    return out, gd, ld, lk_take_messages!(ld)
end

@testset "set_prolog_flag/2, create_prolog_flag/3 and the flag side effects as swipl's (sf01-sf90)" begin
    f, names = _sf_file()
    kl, _, _ = _sf_kernel(f, names)
    @test length(kl) == length(_SF_PINNED)
    for (k, p) in zip(kl, _SF_PINNED)
        k == p || println(stderr, "  ours  ", k, "\n  swipl ", p)
        @test k == p
    end
    # not vacuous: the pins hold both kinds of answer — a raised error (permission, type, domain, instantiation) and a value read back
    raised = "c[114,97,105,115,101,100]"                 # raised(…)
    @test count(l -> occursin(raised, l), _SF_PINNED) >= 30
    @test count(l -> !occursin(raised, l) && startswith(l, "t_"), _SF_PINNED) >= 30
    @test any(
        l ->
            startswith(l, "t_sf01 ") && occursin(
                "c[112,101,114,109,105,115,115,105,111,110,95,101,114,114,111,114]/3(", l
            ),
        _SF_PINNED
    )
end

# unknown=warning, sf90's call of an undefined predicate (a flipped known difference: DWIM1 registered `dwim_match/3` and `$dwim_predicate/2`,
# pl-dwim.c, so ours == theirs; refusal-flip rule D-0375/D-0376).
# swipl 10.1.19 (a message_hook collector, kinds error and warning, in the order printed) sees TWO messages:
#   1. unknown_in_module_user
#   2. error(existence_error(procedure, zz_nopred_xx/0), _)
# and the call fails (the pinned `t_sf90 no`). The kernel prints message 2 through print_message/2, which translates it BEFORE the
# hook (messages.pl:337 -> dwim_predicates/2 messages.pl:466-470 -> dwim_predicate/2 dwim.pl:449-457 -> dwim_pred/2 -> find_sim_pred
# dwim.pl:331 `'$dwim_predicate'(Module:Name, Term)`). The row catches with a variable, so a raise from that translation (the old
# existence_error of `'$dwim':'$dwim_predicate'/2`) would show as `ok(Error)` and not as `no`; it compares the WHOLE message list
# and the answer with swipl's.
const _SF90_PROGRAM = raw"""
t_sf90w(R) :- set_prolog_flag(unknown, warning), ( catch(zz_nopred_xx, E, true) -> R = ok(E) ; R = no ), set_prolog_flag(unknown, error).
"""
_sf_c(name::String, args::Vector{String}) =
    "c" * _sf_codes(name) * "/$(length(args))(" * join(args, ",") * ")"
_sf_a(name::String) = "a" * _sf_codes(name)
# swipl's two messages as the driver's enc/1 writes them (the pinned expected-flip value)
const _SF90_PINNED = [
    _sf_a("unknown_in_module_user"),
    _sf_c(
        "error",
        [
            _sf_c(
                "existence_error",
                [_sf_a("procedure"), _sf_c("/", [_sf_a("zz_nopred_xx"), "i0"])]
            ),
            "V0"
        ]
    )
]
# the answer `t_sf90w` binds, as swipl gives it: the call fails (no exception reaches the catch)
const _SF90_ANSWER = _sf_a("no")

"The kernel's collected messages (encoded) and the answer line of `t_sf90w`, on a fresh database."
function _sf90_kernel()
    path = joinpath(mktempdir(), "sf90.pl")
    write(path, _SF90_PROGRAM)
    gd = LK.PL_global_data{_SF}()
    ld = LK.PL_local_data{_SF}(gd)
    lk_install_message_collector!(gd, ld)
    st, ball = LK.load_file!(gd, ld, path)
    st === :ok || error("sf90 program did not load: $st $(_sf_enc(ball::_SF))")
    lk_take_messages!(ld)
    line = _sf_query(gd, ld, "t_sf90w")
    return [
        _sf_enc(m[2]) for m in lk_take_messages!(ld) if m[1] === :warning || m[1] === :error
    ],
    line
end

# swipl's side: the same program, the collector `user:message_hook/3` recording error and warning messages (and failing, so they print)
function _sf90_swipl()::Vector{String}
    out = mktempdir() do d
        f = joinpath(d, "drv.pl")
        write(
            f,
            _SF_DRIVER * ":- dynamic seen/1.\n" *
            "user:message_hook(T, K, _) :- ( K == error ; K == warning ), assertz(seen(T)), fail.\n" *
            _SF90_PROGRAM *
            ":- initialization((catch(t_sf90w(R), _, R = exc), forall(seen(T), (enc(T), nl)), enc(R), nl, halt)).\n"
        )
        read(pipeline(`swipl -q $f`; stdin=devnull, stderr=devnull), String)
    end
    return String.(split(chomp(out), '\n'; keepempty=false))
end

@testset "unknown=warning: swipl prints unknown_in_module_user and the existence_error; the kernel's messages and answer are the same (DWIM1)" begin
    msgs, line = _sf90_kernel()
    # ours == theirs: both messages in order, and the call fails (a raise would bind `ok(Error)`)
    @test length(_SF90_PINNED) == 2
    @test msgs == _SF90_PINNED
    @test line == "t_sf90w " * _sf_c("t_sf90w", [_SF90_ANSWER])
    swipl = get(ENV, "LOGICKERNEL_NO_SWIPL", "") == "1" ? nothing : Sys.which("swipl")
    if swipl !== nothing
        @test _sf90_swipl() == [_SF90_PINNED; _sf_a("no")]
    end
end

@testset "the pins are swipl's (live, when swipl is on PATH)" begin
    swipl = get(ENV, "LOGICKERNEL_NO_SWIPL", "") == "1" ? nothing : Sys.which("swipl")
    # the pinned table is the driver's whole output (the inert-testset guard: an assertion either way)
    @test length(_SF_PINNED) == length(_SF_CASES) + 1
    if swipl === nothing
        @info "F1b LIVE CHECK NOT RUN: `swipl` is not on PATH here. It runs in tools/run_tests.sh and CI."
    else
        f, names = _sf_file()
        @test _sf_swipl_lines(f, names) == _SF_PINNED
    end
end

# the flags refused BY NAME (design D4; `debug` and `debugger_show_context` are accepted since R2 F1c: test_debug_flag_swipl.jl): the flag is DEFINED at upstream's default and setting it raises `NotPortedError` naming the
# side effect that lives in a file not yet ported; a value the flag accepts is given, so the refusal is the answer, not a type error
# Values swipl 10.1.19 accepts for the flag (probed); the kernel checks oneof and read-only BEFORE it refuses, so a
# value outside the flag's domain would end in a different error. `file_name_case_handling` is READ-ONLY (swipl and the
# kernel answer permission_error(modify, flag, file_name_case_handling)): it has no row here.
const _SF_REFUSED = [
    ("tty_control", "true"), ("debug_on_interrupt", "true"), ("var_tag", "dict"),
    ("incomparable", "error"), ("encoding", "utf8"), ("unicode_atoms", "error"),
    ("table_monotonic", "lazy"),
    ("theme", "dark"), ("agc_margin", "100"), ("table_space", "1000000"),
    ("table_compile_threshold", "5"), ("table_drop_intermediate", "5"),
    ("stack_limit", "1000000000"),
    ("heartbeat", "0"),
    ("float_overflow", "infinity"), ("max_answers_for_subgoal", "5"),
    ("max_table_subgoal_size", "5"),
    ("max_incomplete_subgoals", "5"), ("max_scc_subgoals", "5")
]

@testset "the flags refused by name raise NotPortedError (design D4)" begin
    text = join([
        "r_$(f)(R) :- set_prolog_flag($f, $v), R = ok.\n" for (f, v) in _SF_REFUSED
    ])
    path = joinpath(mktempdir(), "refused.pl")
    write(path, text)
    for (f, _) in _SF_REFUSED
        gd = LK.PL_global_data{_SF}()
        ld = LK.PL_local_data{_SF}(gd)
        st, _ = LK.load_file!(gd, ld, path)
        @test st === :ok
        # UNVERIFIED on the kernel: gate decides (the refusal's class for `threads`, `tty_control`: the value that changes the flag)
        @test_throws LK.NotPortedError _sf_query(gd, ld, "r_$(f)")
    end
    @test length(_SF_REFUSED) >= 19
end

# KNOWN DIFFERENCE BY DESIGN (D1, the no-threads build; checklist: R2's threads): `threads` is read-only in the kernel (upstream's `#else` of
# `O_PLMT`: `FT_BOOL|FF_READONLY, false`), so setting it answers permission_error(modify, flag, threads); swipl 10.1.19 (a threaded
# build) accepts `set_prolog_flag(threads, true)`, its current value. `string_stack_tripwire` is no flag of swipl's boot: the first set
# creates a user flag, as swipl 10.1.19 does (probed), and the second reaches the refusal.
@testset "threads is read-only in the no-threads build (design D1)" begin
    path = joinpath(mktempdir(), "threads.pl")
    write(
        path,
        "t_th(R) :- catch(set_prolog_flag(threads, true), error(E, _), true), R = E.\n" *
        "t_sst(R) :- set_prolog_flag(string_stack_tripwire, 100), set_prolog_flag(string_stack_tripwire, 100), R = ok.\n"
    )
    gd = LK.PL_global_data{_SF}()
    ld = LK.PL_local_data{_SF}(gd)
    LK.load_file!(gd, ld, path)
    line = _sf_query(gd, ld, "t_th")
    @test occursin(
        "c" * _sf_codes("permission_error") * "/3(a" * _sf_codes("modify") * ",a" *
        _sf_codes("flag") * ",a" * _sf_codes("threads") * ")",
        line
    )
    @test_throws LK.NotPortedError _sf_query(gd, ld, "t_sst")
end

# the kernel's answer where swipl 10.1.19 does not answer: `set_prolog_flag(user_flags, error)`, then a new key — the
# kernel raises existence_error(prolog_flag, K) at once (pl-prologflag.c check_create_flag)
@testset "user_flags=error and a new key: the kernel's answer (swipl 10.1.19 does not answer this case)" begin
    path = joinpath(mktempdir(), "uferr.pl")
    write(
        path,
        "t_uf(R) :- set_prolog_flag(user_flags, error), catch(set_prolog_flag(zz_uf_new, 1), error(E, _), true), set_prolog_flag(user_flags, silent), R = E.\n"
    )
    gd = LK.PL_global_data{_SF}()
    ld = LK.PL_local_data{_SF}(gd)
    LK.load_file!(gd, ld, path)
    line = _sf_query(gd, ld, "t_uf")
    ek = _sf_codes("existence_error")
    @test occursin(
        "c" * ek * "/2(a" * _sf_codes("prolog_flag") * ",a" * _sf_codes("zz_uf_new") * ")",
        line
    )
end
